BEGIN;
CREATE TABLE IF NOT EXISTS public.idmc_cw_policy(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),programme_id uuid NOT NULL REFERENCES programmes(id),academic_year_id uuid NOT NULL REFERENCES academic_years(id),semester_id uuid NOT NULL REFERENCES semesters(id),maximum numeric NOT NULL,minimum numeric NOT NULL,limits jsonb NOT NULL,grade_scale_id uuid NOT NULL REFERENCES grade_scales(id),locked_by uuid NOT NULL REFERENCES users(id),locked_at timestamptz NOT NULL DEFAULT now(),UNIQUE(programme_id,academic_year_id,semester_id));
CREATE TABLE IF NOT EXISTS public.idmc_cw_component(offering_id uuid NOT NULL REFERENCES course_offerings(id),slot text NOT NULL CHECK(slot IN ('INDIVIDUAL','GROUP','TEST1','TEST2')),assessment_id uuid NOT NULL UNIQUE REFERENCES assessments(id),PRIMARY KEY(offering_id,slot));
CREATE TABLE IF NOT EXISTS public.idmc_cw_file(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id uuid NOT NULL REFERENCES assessments(id),student_id uuid REFERENCES students(id),storage_path text NOT NULL UNIQUE,file_name text NOT NULL,mime_type text NOT NULL,uploaded_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,deleted_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS public.idmc_cw_release(assessment_id uuid PRIMARY KEY REFERENCES assessments(id),file_id uuid NOT NULL REFERENCES idmc_cw_file(id),published_at timestamptz,due_at timestamptz,published_by uuid REFERENCES users(id),makeup_closes_at timestamptz);
CREATE TABLE IF NOT EXISTS public.idmc_cw_submission(assessment_id uuid REFERENCES assessments(id),student_id uuid REFERENCES students(id),file_id uuid REFERENCES idmc_cw_file(id),state text NOT NULL DEFAULT 'NOT_SUBMITTED' CHECK(state IN ('NOT_SUBMITTED','SUBMITTED','CONFIRMED','REJECTED','MARKED')),acknowledged boolean NOT NULL DEFAULT false,comment text,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(assessment_id,student_id));
CREATE TABLE IF NOT EXISTS public.idmc_cw_review(offering_id uuid PRIMARY KEY REFERENCES course_offerings(id),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','REVIEWED','RETURNED')),submitted_by uuid REFERENCES users(id),reviewed_by uuid REFERENCES users(id),comment text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.idmc_cw_request(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),offering_id uuid NOT NULL REFERENCES course_offerings(id),target_offering_id uuid REFERENCES course_offerings(id),kind text NOT NULL CHECK(kind IN ('CARRY_OVER','SPECIAL','REPEAT','MAKEUP')),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','COMPLETED')),reason text NOT NULL,comment text,opens_at timestamptz,closes_at timestamptz,decided_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(status NOT IN ('APPROVED','COMPLETED') OR (opens_at IS NOT NULL AND closes_at>opens_at)));
CREATE UNIQUE INDEX IF NOT EXISTS idmc_cw_request_active ON idmc_cw_request(student_id,offering_id,kind) WHERE status IN ('PENDING','APPROVED');
CREATE TABLE IF NOT EXISTS public.idmc_cw_request_mark(request_id uuid REFERENCES idmc_cw_request(id),slot text CHECK(slot IN ('INDIVIDUAL','GROUP','TEST1','TEST2')),percentage numeric NOT NULL CHECK(percentage BETWEEN 0 AND 100),marked_by uuid REFERENCES users(id),PRIMARY KEY(request_id,slot));
CREATE SEQUENCE IF NOT EXISTS public.idmc_exam_number_seq;
CREATE TABLE IF NOT EXISTS public.idmc_cw_exam_card(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),academic_year_id uuid NOT NULL REFERENCES academic_years(id),semester_id uuid NOT NULL REFERENCES semesters(id),exam_number text NOT NULL UNIQUE DEFAULT ('IDMC-EX-'||lpad(nextval('idmc_exam_number_seq')::text,8,'0')),snapshot jsonb NOT NULL,generated_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_id,academic_year_id,semester_id));
CREATE TABLE IF NOT EXISTS public.idmc_cw_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid,action text NOT NULL,actor_id uuid REFERENCES users(id),details jsonb,created_at timestamptz NOT NULL DEFAULT now());
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['idmc_cw_policy','idmc_cw_component','idmc_cw_file','idmc_cw_release','idmc_cw_submission','idmc_cw_review','idmc_cw_request','idmc_cw_request_mark','idmc_cw_exam_card','idmc_cw_event'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT ALL ON TABLE public.%I TO service_role',t);END LOOP;END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_role(actor uuid,codes text[]) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=actor AND ur.status='ACTIVE' AND r.status='ACTIVE' AND (ur.expires_at IS NULL OR ur.expires_at>now()) AND r.role_code=ANY(codes))$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_policy_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'This programme policy is permanently locked';END$$;
DROP TRIGGER IF EXISTS idmc_cw_policy_guard ON idmc_cw_policy;
CREATE TRIGGER idmc_cw_policy_guard BEFORE UPDATE OR DELETE ON idmc_cw_policy FOR EACH ROW EXECUTE FUNCTION idmc_cw_policy_guard();
CREATE OR REPLACE FUNCTION public.idmc_cw_legacy_policy_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$DECLARE grp text;mx numeric;mn numeric;BEGIN IF TG_OP IN ('UPDATE','DELETE') AND OLD.status='LOCKED' THEN RAISE EXCEPTION 'Locked examination policy cannot be changed';END IF;IF TG_OP<>'DELETE' AND NOT idmc_cw_role(coalesce(NEW.approved_by,NEW.created_by),ARRAY['ACADEMIC_OFFICER']) THEN RAISE EXCEPTION 'Only Academic may set examination policy';END IF;IF TG_OP<>'DELETE' AND NEW.status<>'LOCKED' THEN RAISE EXCEPTION 'Academic must lock examination policy';END IF;IF TG_OP<>'DELETE' THEN SELECT d.academic_group INTO grp FROM course_offerings o JOIN programmes p ON p.id=o.programme_id JOIN departments d ON d.id=p.department_id WHERE o.id=NEW.course_offering_id;IF grp='PROJECT' THEN mx:=50;mn:=25;ELSIF grp='SOCIAL' THEN mx:=60;mn:=30;ELSE RAISE EXCEPTION 'Assign programme department group first';END IF;IF NEW.coursework_weight<>mx OR NEW.examination_weight<>100-mx OR NEW.minimum_coursework_required IS DISTINCT FROM mn THEN RAISE EXCEPTION 'Examination policy must use the fixed programme maximum and minimum';END IF;END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END$$;
DROP TRIGGER IF EXISTS idmc_cw_legacy_policy_guard ON course_result_policies;
CREATE TRIGGER idmc_cw_legacy_policy_guard BEFORE INSERT OR UPDATE OR DELETE ON course_result_policies FOR EACH ROW EXECUTE FUNCTION idmc_cw_legacy_policy_guard();
CREATE OR REPLACE FUNCTION public.idmc_cw_lock(p_data jsonb,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
#variable_conflict use_column
DECLARE prog uuid:=(p_data->>'programmeId')::uuid;yr uuid:=(p_data->>'yearId')::uuid;sem uuid:=(p_data->>'semesterId')::uuid;mx numeric;mn numeric;grp text;sum_limits numeric:=0;sl text;o record;pol idmc_cw_policy;BEGIN
 IF NOT idmc_cw_role(p_actor,ARRAY['ACADEMIC_OFFICER']) THEN RAISE EXCEPTION 'Only Academic may lock policy' USING ERRCODE='42501';END IF;
 SELECT d.academic_group INTO grp FROM programmes p JOIN departments d ON d.id=p.department_id WHERE p.id=prog;
 IF grp='PROJECT' THEN mx:=50;mn:=25;ELSIF grp='SOCIAL' THEN mx:=60;mn:=30;ELSE RAISE EXCEPTION 'Assign programme department to PROJECT or SOCIAL first';END IF;
 IF NOT EXISTS(SELECT 1 FROM semesters WHERE id=sem AND academic_year_id=yr) THEN RAISE EXCEPTION 'Semester does not belong to academic year';END IF;
 FOREACH sl IN ARRAY ARRAY['INDIVIDUAL','GROUP','TEST1','TEST2'] LOOP IF coalesce((p_data->'limits'->>sl)::numeric,0)<=0 THEN RAISE EXCEPTION 'Enter a positive allocation for each component';END IF;sum_limits:=sum_limits+(p_data->'limits'->>sl)::numeric;END LOOP;
 IF sum_limits<>mx THEN RAISE EXCEPTION 'Component allocations must total %',mx;END IF;
 IF EXISTS(SELECT 1 FROM course_result_policies cp JOIN course_offerings o ON o.id=cp.course_offering_id WHERE o.programme_id=prog AND o.academic_year_id=yr AND o.semester_id=sem AND cp.status='LOCKED' AND (cp.coursework_weight<>mx OR cp.minimum_coursework_required IS DISTINCT FROM mn OR cp.grade_scale_id IS DISTINCT FROM (p_data->>'gradeScaleId')::uuid)) THEN RAISE EXCEPTION 'An existing offering policy is locked. Review its compatibility before creating a new programme policy';END IF;
 INSERT INTO idmc_cw_policy(programme_id,academic_year_id,semester_id,maximum,minimum,limits,grade_scale_id,locked_by) VALUES(prog,yr,sem,mx,mn,p_data->'limits',(p_data->>'gradeScaleId')::uuid,p_actor) RETURNING * INTO pol;
 INSERT INTO idmc_cw_event(entity_id,action,actor_id,details) VALUES(pol.id,'ACADEMIC_POLICY_LOCKED',p_actor,(SELECT coalesce(jsonb_agg(to_jsonb(cp)),'[]') FROM course_result_policies cp JOIN course_offerings co ON co.id=cp.course_offering_id WHERE co.programme_id=prog AND co.academic_year_id=yr AND co.semester_id=sem));
 FOR o IN SELECT id FROM course_offerings WHERE programme_id=prog AND academic_year_id=yr AND semester_id=sem AND NOT EXISTS(SELECT 1 FROM course_result_policies cp WHERE cp.course_offering_id=course_offerings.id AND cp.status='LOCKED') LOOP
 INSERT INTO course_result_policies(course_offering_id,grade_scale_id,coursework_weight,examination_weight,minimum_coursework_required,minimum_pass_mark,status,created_by,approved_by,approved_at) VALUES(o.id,pol.grade_scale_id,mx,100-mx,mn,40,'LOCKED',p_actor,p_actor,now()) ON CONFLICT(course_offering_id) DO UPDATE SET grade_scale_id=EXCLUDED.grade_scale_id,coursework_weight=EXCLUDED.coursework_weight,examination_weight=EXCLUDED.examination_weight,minimum_coursework_required=EXCLUDED.minimum_coursework_required,status='LOCKED',approved_by=p_actor,approved_at=now();END LOOP;
 RETURN to_jsonb(pol);END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_setup(p_offering uuid,p_actor uuid,p_mapping jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
#variable_conflict use_column
DECLARE sl text;aid uuid;x jsonb;n integer:=0;BEGIN
 PERFORM 1 FROM course_offerings WHERE id=p_offering FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Offering not found';END IF;
 IF p_mapping IS NOT NULL THEN
 IF NOT idmc_cw_role(p_actor,ARRAY['ACADEMIC_OFFICER']) OR jsonb_array_length(p_mapping)<>4 THEN RAISE EXCEPTION 'Academic must map all four existing assessments';END IF;
 IF (SELECT count(DISTINCT v->>'slot') FROM jsonb_array_elements(p_mapping) v)<>4 OR (SELECT count(DISTINCT v->>'assessmentId') FROM jsonb_array_elements(p_mapping) v)<>4 THEN RAISE EXCEPTION 'Mappings must be unique';END IF;
 IF EXISTS(SELECT 1 FROM idmc_cw_component WHERE offering_id=p_offering) THEN RAISE EXCEPTION 'Assessment components already mapped';END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(p_mapping) LOOP INSERT INTO idmc_cw_component SELECT p_offering,x->>'slot',id FROM assessments WHERE id=(x->>'assessmentId')::uuid AND course_offering_id=p_offering;GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'Assessment is outside offering';END IF;END LOOP;
 ELSE
 IF EXISTS(SELECT 1 FROM assessments a JOIN assessment_marks m ON m.assessment_id=a.id WHERE a.course_offering_id=p_offering AND NOT EXISTS(SELECT 1 FROM idmc_cw_component c WHERE c.assessment_id=a.id)) THEN RAISE EXCEPTION 'Historical marks exist. Academic must map the four existing assessments explicitly';END IF;
 UPDATE assessments a SET status='CANCELLED' WHERE a.course_offering_id=p_offering AND NOT EXISTS(SELECT 1 FROM idmc_cw_component c WHERE c.assessment_id=a.id) AND NOT EXISTS(SELECT 1 FROM assessment_marks m WHERE m.assessment_id=a.id) AND NOT EXISTS(SELECT 1 FROM assessment_submissions s WHERE s.assessment_id=a.id);
 FOREACH sl IN ARRAY ARRAY['INDIVIDUAL','GROUP','TEST1','TEST2'] LOOP IF NOT EXISTS(SELECT 1 FROM idmc_cw_component WHERE offering_id=p_offering AND slot=sl) THEN INSERT INTO assessments(course_offering_id,assessment_code,assessment_name,assessment_type,maximum_marks,weight_percentage,status,created_by) VALUES(p_offering,'CW_'||sl,sl,CASE WHEN sl IN ('TEST1','TEST2') THEN 'TEST' ELSE 'ASSIGNMENT' END,100,25,'OPEN',p_actor) ON CONFLICT(course_offering_id,assessment_code) DO UPDATE SET status='OPEN' RETURNING id INTO aid;INSERT INTO idmc_cw_component VALUES(p_offering,sl,aid);END IF;END LOOP;
 END IF;RETURN (SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM idmc_cw_component c WHERE offering_id=p_offering);END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_score(p_student uuid,p_offering uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$
#variable_conflict use_column
DECLARE pol idmc_cw_policy;c record;m numeric;points numeric;total numeric:=0;scores jsonb:='{}';complete boolean:=true;BEGIN
 SELECT p.* INTO pol FROM idmc_cw_policy p JOIN students s ON s.programme_id=p.programme_id JOIN course_offerings o ON o.id=p_offering WHERE s.id=p_student AND p.academic_year_id=o.academic_year_id AND p.semester_id=o.semester_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('complete',false,'pass',false,'reason','Academic policy is not configured');END IF;
 IF (SELECT count(*) FROM idmc_cw_component WHERE offering_id=p_offering)<>4 THEN complete:=false;END IF;
 FOR c IN SELECT cc.*,a.maximum_marks FROM idmc_cw_component cc JOIN assessments a ON a.id=cc.assessment_id WHERE cc.offering_id=p_offering LOOP
 SELECT mk.marks/c.maximum_marks*100 INTO m FROM assessment_marks mk WHERE mk.assessment_id=c.assessment_id AND mk.student_id=p_student AND mk.status IN ('SUBMITTED','APPROVED','LOCKED') LIMIT 1;
 SELECT rm.percentage INTO points FROM idmc_cw_request_mark rm JOIN idmc_cw_request r ON r.id=rm.request_id WHERE r.student_id=p_student AND r.offering_id=p_offering AND r.status='COMPLETED' AND rm.slot=c.slot ORDER BY r.created_at DESC LIMIT 1;IF FOUND THEN m:=points;END IF;
 IF m IS NULL THEN complete:=false;points:=NULL;ELSE points:=round(m*(pol.limits->>c.slot)::numeric/100,2);total:=total+points;END IF;
 IF c.slot IN ('INDIVIDUAL','GROUP') AND EXISTS(SELECT 1 FROM idmc_cw_release WHERE assessment_id=c.assessment_id AND published_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM idmc_cw_submission WHERE assessment_id=c.assessment_id AND student_id=p_student AND file_id IS NOT NULL AND state IN ('CONFIRMED','MARKED')) THEN complete:=false;END IF;
 scores:=scores||jsonb_build_object(c.slot,points);END LOOP;
 RETURN jsonb_build_object('scores',scores,'coursework',total,'maximum',pol.maximum,'minimum',pol.minimum,'complete',complete,'pass',complete AND total>=pol.minimum);END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_eligible(p_student uuid,p_year uuid,p_semester uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$
#variable_conflict use_column
DECLARE r record;s jsonb;n integer:=0;BEGIN
 FOR r IN SELECT o.id FROM course_registrations cr JOIN course_offerings o ON o.id=cr.course_offering_id WHERE cr.student_id=p_student AND cr.registration_status IN ('REGISTERED','APPROVED') AND o.academic_year_id=p_year AND o.semester_id=p_semester LOOP n:=n+1;s:=idmc_cw_score(p_student,r.id);IF NOT coalesce((s->>'complete')::boolean,false) OR NOT coalesce((s->>'pass')::boolean,false) THEN RETURN jsonb_build_object('eligible',false,'reason','Complete all four components and minimum coursework for every registered course');END IF;END LOOP;
 IF n=0 THEN RETURN jsonb_build_object('eligible',false,'reason','No registered courses');END IF;
 IF NOT EXISTS(SELECT 1 FROM student_registrations WHERE student_id=p_student AND academic_year_id=p_year AND semester_id=p_semester AND finance_eligibility_status='CLEARED') OR NOT EXISTS(SELECT 1 FROM student_financial_accounts WHERE student_id=p_student AND current_balance<=0) THEN RETURN jsonb_build_object('eligible',false,'reason','Finance clearance and settled account are required');END IF;RETURN jsonb_build_object('eligible',true);END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_submit(p_offering uuid,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
#variable_conflict use_column
DECLARE c record;r record;BEGIN
 FOR c IN SELECT * FROM idmc_cw_component WHERE offering_id=p_offering LOOP FOR r IN SELECT student_id FROM course_registrations WHERE course_offering_id=p_offering AND registration_status IN ('APPROVED','REGISTERED') LOOP IF NOT EXISTS(SELECT 1 FROM assessment_marks WHERE assessment_id=c.assessment_id AND student_id=r.student_id AND marks IS NOT NULL) THEN RAISE EXCEPTION 'Every student needs all four component marks';END IF;END LOOP;END LOOP;
 IF (SELECT count(*) FROM idmc_cw_component WHERE offering_id=p_offering)<>4 THEN RAISE EXCEPTION 'Map the four assessment components first';END IF;
 UPDATE assessment_marks SET status='SUBMITTED',submitted_by=p_actor,submitted_at=now() WHERE assessment_id IN (SELECT assessment_id FROM idmc_cw_component WHERE offering_id=p_offering) AND status='DRAFT';UPDATE assessments SET status='SUBMITTED' WHERE id IN (SELECT assessment_id FROM idmc_cw_component WHERE offering_id=p_offering) AND status IN ('DRAFT','OPEN');
 INSERT INTO idmc_cw_review(offering_id,submitted_by) VALUES(p_offering,p_actor) ON CONFLICT(offering_id) DO UPDATE SET status='PENDING',submitted_by=p_actor,updated_at=now();RETURN jsonb_build_object('submitted',true,'studentVisible',true,'hodReview','PENDING');END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_card(p_student uuid,p_year uuid,p_semester uuid,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
#variable_conflict use_column
DECLARE e jsonb;s students;photo text;card idmc_cw_exam_card;BEGIN
 IF NOT idmc_cw_role(p_actor,ARRAY['ACADEMIC_OFFICER']) THEN RAISE EXCEPTION 'Only Academic generates exam cards' USING ERRCODE='42501';END IF;e:=idmc_cw_eligible(p_student,p_year,p_semester);IF NOT (e->>'eligible')::boolean THEN RETURN e;END IF;SELECT * INTO s FROM students WHERE id=p_student;SELECT coalesce(s.profile_photo_url,sp.profile_photo_url) INTO photo FROM student_profiles sp WHERE sp.student_id=p_student;photo:=coalesce(photo,s.profile_photo_url);IF photo IS NULL THEN RETURN jsonb_build_object('eligible',false,'reason','Passport photo is required');END IF;
 INSERT INTO idmc_cw_exam_card(student_id,academic_year_id,semester_id,snapshot,generated_by) VALUES(p_student,p_year,p_semester,jsonb_build_object('name',concat_ws(' ',s.first_name,s.middle_name,s.last_name),'registrationNumber',coalesce(s.registration_number,s.student_number),'photo',photo,'yearName',(SELECT year_name FROM academic_years WHERE id=p_year),'semesterName',(SELECT semester_name FROM semesters WHERE id=p_semester)),p_actor) ON CONFLICT(student_id,academic_year_id,semester_id) DO NOTHING;SELECT * INTO card FROM idmc_cw_exam_card WHERE student_id=p_student AND academic_year_id=p_year AND semester_id=p_semester;
 INSERT INTO examination_candidates(examination_paper_id,student_id,course_registration_id,candidate_number,eligibility_status,candidate_status) SELECT ep.id,p_student,cr.id,card.exam_number,'ELIGIBLE','ACTIVE' FROM examination_papers ep JOIN course_offerings o ON o.id=ep.course_offering_id JOIN course_registrations cr ON cr.course_offering_id=o.id AND cr.student_id=p_student AND cr.registration_status IN ('APPROVED','REGISTERED') WHERE o.academic_year_id=p_year AND o.semester_id=p_semester AND ep.status<>'CANCELLED' ON CONFLICT(examination_paper_id,student_id) DO UPDATE SET candidate_number=EXCLUDED.candidate_number,eligibility_status='ELIGIBLE';RETURN jsonb_build_object('eligible',true,'card',to_jsonb(card));END$$;
CREATE OR REPLACE FUNCTION public.idmc_cw_complete_request(p_request uuid,p_marks jsonb,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
#variable_conflict use_column
DECLARE r idmc_cw_request;x jsonb;BEGIN SELECT * INTO r FROM idmc_cw_request WHERE id=p_request FOR UPDATE;IF r.status<>'APPROVED' OR now() NOT BETWEEN r.opens_at AND r.closes_at THEN RAISE EXCEPTION 'Academic request window is not open';END IF;IF NOT EXISTS(SELECT 1 FROM lecturer_assignments WHERE lecturer_user_id=p_actor AND assignment_status='ACTIVE' AND course_offering_id=coalesce(r.target_offering_id,r.offering_id)) OR NOT idmc_cw_role(p_actor,ARRAY['LECTURER']) THEN RAISE EXCEPTION 'Only assigned lecturer may mark this request';END IF;
 IF jsonb_array_length(p_marks)<>4 OR (SELECT count(DISTINCT v->>'slot') FROM jsonb_array_elements(p_marks) v)<>4 THEN RAISE EXCEPTION 'Provide all four component percentages';END IF;FOR x IN SELECT * FROM jsonb_array_elements(p_marks) LOOP INSERT INTO idmc_cw_request_mark VALUES(p_request,x->>'slot',(x->>'marks')::numeric,p_actor) ON CONFLICT(request_id,slot) DO UPDATE SET percentage=EXCLUDED.percentage,marked_by=p_actor;END LOOP;UPDATE idmc_cw_request SET status='COMPLETED' WHERE id=p_request;INSERT INTO idmc_cw_event(entity_id,action,actor_id,details) VALUES(p_request,'REQUEST_MARKED',p_actor,p_marks);RETURN jsonb_build_object('completed',true);END$$;
REVOKE ALL ON FUNCTION idmc_cw_lock(jsonb,uuid),idmc_cw_setup(uuid,uuid,jsonb),idmc_cw_score(uuid,uuid),idmc_cw_eligible(uuid,uuid,uuid),idmc_cw_submit(uuid,uuid),idmc_cw_card(uuid,uuid,uuid,uuid),idmc_cw_complete_request(uuid,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION idmc_cw_lock(jsonb,uuid),idmc_cw_setup(uuid,uuid,jsonb),idmc_cw_score(uuid,uuid),idmc_cw_eligible(uuid,uuid,uuid),idmc_cw_submit(uuid,uuid),idmc_cw_card(uuid,uuid,uuid,uuid),idmc_cw_complete_request(uuid,jsonb,uuid) TO service_role;
GRANT USAGE,SELECT ON SEQUENCE idmc_exam_number_seq TO service_role;

CREATE OR REPLACE FUNCTION public.idmc_cw_result_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
#variable_conflict use_column
DECLARE pol idmc_cw_policy;sc jsonb;g record;exam_raw numeric;exam_max numeric;BEGIN
 SELECT p.* INTO pol FROM idmc_cw_policy p JOIN students s ON s.programme_id=p.programme_id WHERE s.id=NEW.student_id AND p.academic_year_id=NEW.academic_year_id AND p.semester_id=NEW.semester_id;
 IF NOT FOUND OR NEW.result_status IN ('DRAFT','CANCELLED') THEN RETURN NEW;END IF;
 sc:=idmc_cw_score(NEW.student_id,NEW.course_offering_id);IF NOT (sc->>'complete')::boolean THEN RAISE EXCEPTION 'Complete all four assessments before calculating final results';END IF;
 SELECT sum(em.marks),sum(ep.maximum_marks) INTO exam_raw,exam_max FROM examination_marks em JOIN examination_papers ep ON ep.id=em.examination_paper_id JOIN examination_candidates ec ON ec.id=em.examination_candidate_id WHERE em.student_id=NEW.student_id AND ep.course_offering_id=NEW.course_offering_id AND em.status IN ('APPROVED','LOCKED') AND ec.eligibility_status='ELIGIBLE' AND ec.candidate_status='ACTIVE';
 IF exam_max>0 AND NEW.examination_mark IS NOT NULL THEN NEW.examination_mark:=round(exam_raw/exam_max*(100-pol.maximum),2);END IF;
 IF NEW.examination_mark IS NOT NULL AND (NEW.examination_mark<0 OR NEW.examination_mark>100-pol.maximum) THEN RAISE EXCEPTION 'Examination mark exceeds student programme maximum %',100-pol.maximum;END IF;
 NEW.coursework_mark:=(sc->>'coursework')::numeric;NEW.total_mark:=NEW.coursework_mark+coalesce(NEW.examination_mark,0);SELECT * INTO g FROM get_grade_for_mark(pol.grade_scale_id,NEW.total_mark);IF NOT FOUND THEN RAISE EXCEPTION 'Grade scale does not cover the total mark';END IF;NEW.grade_code:=g.grade_code;NEW.grade_point:=g.grade_point;NEW.pass_status:=CASE WHEN NOT (sc->>'pass')::boolean THEN 'FAIL' ELSE g.pass_status END;RETURN NEW;END$$;
DROP TRIGGER IF EXISTS aaa_idmc_cw_result_guard ON course_results;
CREATE TRIGGER aaa_idmc_cw_result_guard BEFORE INSERT OR UPDATE ON course_results FOR EACH ROW EXECUTE FUNCTION idmc_cw_result_guard();
CREATE OR REPLACE FUNCTION public.idmc_result_workspace(p_actor uuid,p_mode text,p_offset integer,p_limit integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE answer jsonb; total bigint;
BEGIN
 IF p_mode NOT IN ('HOD','PRINCIPAL') OR p_offset IS NULL OR p_offset<0 OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid results page'; END IF;
 IF NOT public.idmc_result_actor(p_actor,p_mode,CASE WHEN p_mode='HOD' THEN 'results.hod.publish' ELSE 'results.principal.comment' END) THEN RAISE EXCEPTION 'Active results workspace role required' USING ERRCODE='42501'; END IF;
 SELECT count(*) INTO total FROM public.course_results r JOIN public.course_offerings o ON o.id=r.course_offering_id JOIN public.courses c ON c.id=o.course_id
 WHERE (p_mode='HOD' AND public.idmc_hod_department(p_actor,c.department_id) AND r.result_status IN ('CALCULATED','SUBMITTED','HOD_VERIFIED','EXAMINATION_REVIEWED','DEPUTY_REVIEWED','PRINCIPAL_APPROVED','VERIFIED','APPROVED','PUBLISHED','LOCKED'))
 OR (p_mode='PRINCIPAL' AND r.result_status IN ('PUBLISHED','LOCKED'));
 SELECT coalesce(jsonb_agg(to_jsonb(rows)),'[]') INTO answer FROM (
 SELECT r.id,r.result_status,r.total_mark,r.grade_code,r.student_id,s.student_number,concat_ws(' ',s.first_name,s.middle_name,s.last_name) student_name,
 concat_ws(' · ',c.course_code,c.course_name) course_label,y.year_name academic_year,se.semester_name,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('id',cm.id,'comment',cm.comment,'createdAt',cm.created_at,'principal',coalesce(u.display_name,u.email)) ORDER BY cm.created_at),'[]') FROM public.idmc_result_comments cm JOIN public.users u ON u.id=cm.principal_user_id WHERE cm.result_id=r.id) comments
 FROM public.course_results r JOIN public.course_offerings o ON o.id=r.course_offering_id JOIN public.courses c ON c.id=o.course_id
 JOIN public.students s ON s.id=r.student_id LEFT JOIN public.academic_years y ON y.id=r.academic_year_id LEFT JOIN public.semesters se ON se.id=r.semester_id
 WHERE (p_mode='HOD' AND public.idmc_hod_department(p_actor,c.department_id) AND r.result_status IN ('CALCULATED','SUBMITTED','HOD_VERIFIED','EXAMINATION_REVIEWED','DEPUTY_REVIEWED','PRINCIPAL_APPROVED','VERIFIED','APPROVED','PUBLISHED','LOCKED'))
 OR (p_mode='PRINCIPAL' AND r.result_status IN ('PUBLISHED','LOCKED'))
 ORDER BY r.updated_at DESC,r.id LIMIT p_limit OFFSET p_offset) rows;
 RETURN jsonb_build_object('items',answer,'total',total,'offset',p_offset,'limit',p_limit);
END $$;

CREATE OR REPLACE FUNCTION public.idmc_cw_offering_policy() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
DECLARE p idmc_cw_policy;BEGIN SELECT * INTO p FROM idmc_cw_policy WHERE programme_id=NEW.programme_id AND academic_year_id=NEW.academic_year_id AND semester_id=NEW.semester_id;IF FOUND THEN INSERT INTO course_result_policies(course_offering_id,grade_scale_id,coursework_weight,examination_weight,minimum_coursework_required,status,created_by,approved_by,approved_at) VALUES(NEW.id,p.grade_scale_id,p.maximum,100-p.maximum,p.minimum,'LOCKED',p.locked_by,p.locked_by,now()) ON CONFLICT(course_offering_id) DO NOTHING;END IF;RETURN NEW;END$$;
DROP TRIGGER IF EXISTS idmc_cw_offering_policy ON course_offerings;
CREATE TRIGGER idmc_cw_offering_policy AFTER INSERT ON course_offerings FOR EACH ROW EXECUTE FUNCTION idmc_cw_offering_policy();
CREATE OR REPLACE FUNCTION public.idmc_hod_review_calculated(p_result uuid,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE r course_results;dept uuid;sc jsonb;BEGIN SELECT * INTO r FROM course_results WHERE id=p_result FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Result not found';END IF;SELECT c.department_id INTO dept FROM course_offerings o JOIN courses c ON c.id=o.course_id WHERE o.id=r.course_offering_id;IF NOT idmc_hod_department(p_actor,dept) THEN RAISE EXCEPTION 'Only the department HOD may review this result' USING ERRCODE='42501';END IF;IF r.result_status<>'CALCULATED' THEN RAISE EXCEPTION 'Result must be CALCULATED before HOD preparation';END IF;sc:=idmc_cw_score(r.student_id,r.course_offering_id);IF NOT coalesce((sc->>'complete')::boolean,false) THEN RAISE EXCEPTION 'Academic policy and all four completed assessments are required';END IF;
 UPDATE course_results SET result_status='SUBMITTED',submitted_by=p_actor,submitted_at=now(),updated_at=now() WHERE id=p_result;
 UPDATE course_results SET result_status='HOD_VERIFIED',hod_verified_by=p_actor,hod_verified_at=now(),updated_at=now() WHERE id=p_result;
 INSERT INTO idmc_cw_event(entity_id,action,actor_id) VALUES(p_result,'HOD_REVIEWED_CALCULATED_RESULT',p_actor);RETURN jsonb_build_object('reviewed',true,'readyForPublication',true);END$$;
REVOKE ALL ON FUNCTION idmc_hod_review_calculated(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION idmc_hod_review_calculated(uuid,uuid) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
